const { usedBytes } = require('./usage');
const { shardFor } = require('./shard');
const { quotaBytes } = require('./plans');

function acceptUpload(account, file) {
  const after = usedBytes(account.files) + file.size;
  if (after > quotaBytes(account.plan)) {
    return { ok: false, reason: 'over quota' };
  }
  account.files.push(file);
  return { ok: true, shard: shardFor(file.name) };
}

module.exports = { acceptUpload };

