files.src/retry.js:
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function withRetries(fn, retries, delayMs = 200) {
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (attempt > 0) await sleep(delayMs * 2 ** (attempt - 1));
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

module.exports = { withRetries };

files.src/deliver.js:
const { sign } = require('./sign');
const deadLetters = require('./dead-letters');
const { withRetries } = require('./retry');

const DEFAULT_RETRIES = 3;

async function deliverOnce(transport, sub, body, retries, delayMs) {
  const headers = { 'content-type': 'application/json', 'x-signature': sign(sub.secret, body) };
  try {
    return withRetries(() => transport.post(sub.url, body, headers), retries, delayMs).then(() => ({ id: sub.id, ok: true }));
  } catch (err) {
    deadLetters.record(sub.id, err.message);
    return { id: sub.id, ok: false };
  }
}

async function deliverAll(transport, subs, event, options = {}) {
  const body = JSON.stringify(event);
  const retries = options.retries ?? DEFAULT_RETRIES;
  const results = [];
  for (const sub of subs) results.push(await deliverOnce(transport, sub, body, retries, options.delayMs));
  return results;
}

module.exports = { deliverAll };

