const test = require('node:test');
const assert = require('node:assert');
const { withRetries } = require('../src/retry');

test('a flaky call succeeds on a retry', async () => {
  let calls = 0;
  const result = await withRetries(async () => { calls++; if (calls < 3) throw new Error('flaky'); return 'done'; }, 3, 0);
  assert.strictEqual(result, 'done');
  assert.strictEqual(calls, 3);
});

test('gives up after the first try plus the retries', async () => {
  let calls = 0;
  await assert.rejects(withRetries(async () => { calls++; throw new Error('down'); }, 2, 0), /down/);
  assert.strictEqual(calls, 3);
});

