const READ = 1;
const COMMENT = 2;
const WRITE = 4;
const ADMIN = 8;

function hasRight(mask, right) {
  return (mask & right) === right;
}

function toggleRight(mask, right) {
  return mask ^ right;
}

module.exports = { READ, COMMENT, WRITE, ADMIN, hasRight, toggleRight };

files.src/ownership.js:
const { READ, COMMENT, WRITE, ADMIN } = require('./rights');

const OWNER = READ | COMMENT | WRITE | ADMIN;

function transferOwnership(doc, fromUser, toUser) {
  doc.shares[fromUser] &= ~ADMIN;
  doc.shares[toUser] = OWNER;
  doc.owner = toUser;
}

module.exports = { transferOwnership, OWNER };

files.test/rights.test.js:
const test = require('node:test');
const assert = require('node:assert');
const { READ, WRITE, ADMIN, toggleRight } = require('../src/rights');
const { transferOwnership, OWNER } = require('../src/ownership');

test('a switch turns a right on', () => {
  assert.strictEqual(toggleRight(READ, WRITE), READ | WRITE);
});

test('the new owner gets every right', () => {
  const doc = { owner: 'ana', shares: { ana: OWNER, ben: READ } };
  transferOwnership(doc, 'ana', 'ben');
  assert.strictEqual(doc.owner, 'ben');
  assert.strictEqual(doc.shares.ben, OWNER);
  assert.strictEqual(doc.shares.ana & ADMIN, 0);
});

