# {{project}}

Activity feed API for {{project}}.

GET /feed returns events newest first, a page at a time. Pass the next cursor from one page to get the following page. Cursors are opaque.

files.src/cursor.js:
function encodeCursor(e) {
  return String(e.createdAt);
}

function decodeCursor(s) {
  return { createdAt: Number(s) };
}

module.exports = { encodeCursor, decodeCursor };

files.src/feed.js:
const { encodeCursor, decodeCursor } = require('./cursor');

function newestFirst(a, b) {
  return b.createdAt - a.createdAt;
}

function olderThan(e, c) {
  return e.createdAt < c.createdAt;
}

function feedPage(events, { after, limit = 20 } = {}) {
  const sorted = [...events].sort(newestFirst);
  const rest = after ? sorted.filter((e) => olderThan(e, decodeCursor(after))) : sorted;
  const items = rest.slice(0, limit);
  return { items, next: rest.length > limit ? encodeCursor(items[items.length - 1]) : null };
}

module.exports = { feedPage };

files.src/comments.js:
function commentsPage(comments, { after, limit = 50 } = {}) {
  const sorted = [...comments].sort((a, b) => b.postedAt - a.postedAt || (a.id < b.id ? 1 : -1));
  const rest = after ? sorted.filter((c) => c.postedAt < after.postedAt || (c.postedAt === after.postedAt && c.id < after.id)) : sorted;
  const items = rest.slice(0, limit);
  const last = items[items.length - 1];
  return { items, next: rest.length > limit ? { postedAt: last.postedAt, id: last.id } : null };
}

module.exports = { commentsPage };

