const test = require('node:test');
const assert = require('node:assert');
const { keysetPage, compareKeys } = require('../src/pager');
const { commentsPage } = require('../src/comments');

test('keys compare left to right', () => {
  assert.strictEqual(compareKeys([2, 'a'], [2, 'b']), -1);
  assert.strictEqual(compareKeys(3, 2), 1);
});

test('a page knows whether more rows follow', () => {
  const rows = [5, 4, 3].map((n) => ({ n }));
  assert.deepStrictEqual(keysetPage(rows, null, 2, (r) => r.n), { items: [{ n: 5 }, { n: 4 }], more: true });
  assert.deepStrictEqual(keysetPage(rows, 4, 2, (r) => r.n), { items: [{ n: 3 }], more: false });
});

test('comments that share a timestamp are all paged', () => {
  const comments = ['a', 'b', 'c'].map((id) => ({ id, postedAt: 7 }));
  const first = commentsPage(comments, { limit: 2 });
  const second = commentsPage(comments, { after: first.next, limit: 2 });
  assert.deepStrictEqual([...first.items, ...second.items].map((c) => c.id), ['c', 'b', 'a']);
});

