function buildWhere(filters) {
  const clauses = [];
  const params = [];
  if (filters.category) {
    params.push(filters.category);
    clauses.push('category = $' + params.length);
  }
  if (filters.inStock) {
    clauses.push('stock > 0');
  }
  if (filters.term) {
    const term = filters.term.trim();
    clauses.push("name ILIKE '%" + term + "%'");
