  assert.strictEqual(s.lastSeen, 1000);
});

files.src/idle.js:
const IDLE_TIMEOUT = 30;

function isIdle(session, now) {
  return session.lastSeen + IDLE_TIMEOUT < now;
}

module.exports = { isIdle, IDLE_TIMEOUT };

files.src/backoff.js:
const SECOND = 1000;

function reconnectDelay(attempt) {
  return Math.min(30 * SECOND, SECOND * 2 ** attempt);
}

module.exports = { reconnectDelay };

files.test/idle.test.js:
const test = require('node:test');
const assert = require('node:assert');
const { isIdle } = require('../src/idle');

test('a long-idle session is idle', () => {
  const now = 1_000_000_000;
  assert.strictEqual(isIdle({ lastSeen: now - 60 * 60 * 1000 }, now), true);
});

test('a just-touched session is active', () => {
  const now = 1_000_000_000;
  assert.strictEqual(isIdle({ lastSeen: now }, now), false);
});

files.src/sweep.js:
const { isIdle } = require('./idle');

function sweep(store, now) {
  const kept = {};
  for (const [id, session] of Object.entries(store)) {
    if (!isIdle(session, now)) kept[id] = session;
  }
  return kept;
}

module.exports = { sweep };

files.test/sweep.test.js:
const test = require('node:test');
const assert = require('node:assert');
const { sweep } = require('../src/sweep');

test('sweep drops long-idle sessions', () => {
  const now = 1_000_000_000;
  const store = { a: { lastSeen: now }, b: { lastSeen: now - 2 * 60 * 60 * 1000 } };
  assert.deepStrictEqual(Object.keys(sweep(store, now)), ['a']);
});

